# Load all grids
import os, re

def load():
    d = os.environ.get('RLM_SESSION_DIR', '/tmp')
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end() :].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()
print("Keys:", sorted(G.keys()))

# Let me examine demo 1 in detail
demo_input = G.get('Demo pair 1 input (12x29)')
demo_output = G.get('Demo pair 1 output (12x29)')
test_input = G.get('Test input (22x28)')

if demo_input:
    print("Demo 1 input shape:", len(demo_input), "x", len(demo_input[0]))
    # Only show rows with 3s
    for i, row in enumerate(demo_input):
        if set(row) != {7}:
            print(f"  Row {i}: {row}")
    print()
    # Show the same for output
    for i, row in enumerate(demo_input):
        if set(row) != {7}:
            print(f"  Row {i}: {demo_output[i]}")

# Test if 2s are inside the rectangle defined by hull corners
hull_min_r, hull_max_r = 8, 16
hull_min_c, hull_max_c = 2, 6

print("Testing if 2s are inside rectangle:")
for r in range(len(demo_input)):
    for c in range(len(demo_input[0])):
        if demo_output[r][c] == 2:
            row_inside = hull_min_r <= r <= hull_max_r
            col_inside = hull_min_c <= c <= hull_max_c
            both_inside = row_inside and col_inside
            if not both_inside:
                print(f"2 at ({r},{c}) is OUTSIDE: row={row_inside}, col={col_inside}")
            else:
                print(f"2 at ({r},{c}) is inside: row={r} in [{hull_min_r},{hull_max_r}], col={c} in [{hull_min_c},{hull_max_c}]")
        if demo_output[r][c] == 7 and demo_input[r][c] == 7:
            # Check if this 7 is inside
            row_inside = hull_min_r <= r <= hull_max_r
            col_inside = hull_min_c <= c <= hull_max_c
            if row_inside and col_inside:
                print(f"7 at ({r},{c}) stayed 7 but is INSIDE the rectangle!")

print("\n\nChecking what 7s INSIDE are vs OUTSIDE are...")
inside_7s = []
inside_2s = []
for r in range(len(demo_input)):
    for c in range(len(demo_input[0])):
        row_inside = hull_min_r <= r <= hull_max_r
        col_inside = hull_min_c <= c <= hull_max_c
        if row_inside and col_inside:
            if demo_input[r][c] == 7:
                if demo_output[r][c] == 2:
                    inside_2s.append((r, c))
                else:
                    inside_7s.append((r, c))
if inside_2s:
    print(f"7s that became 2s inside: {inside_2s}")
if inside_7s:
    print(f"7s that stayed 7 inside: {inside_7s}")

# Re-examine the output - 2s locations
print("All 2s in output:")
for r in range(len(demo_output)):
    for c in range(len(demo_output[0])):
        if demo_output[r][c] == 2:
            print(f"  2 at ({r},{c}): input was {demo_input[r][c]}")

print("\n\nAll 3s in output (should match input 3s):")
for r in range(len(demo_output)):
