        if demo_output[r][c] == 7:
            count += 1
print(f"Total 7s: {count}")

# Improved rule: only process columns where 3s appear at both top and bottom edges
def apply_refined_rule(grid_input):
    grid_output = [row[:] for row in grid_input]

    h = len(grid_input)
    w = len(grid_input[0])

    # Find all 3s
    threes = set()
    for r in range(h):
        for c in range(w):
            if grid_input[r][c] == 3:
                threes.add((r, c))

    min_row = min(r for r, c in threes)
    max_row = max(r for r, c in threes)
    min_col = min(c for r, c in threes)
    max_col = max(c for r, c in threes)

    # Edge columns: have 3s at both top edge (min_row) and bottom edge (max_row)
    edge_cols = [c for c in range(w) 
                 if (min_row, c) in threes and (max_row, c) in threes]

    # Edge rows: have 3s at both left edge (min_col) and right edge (max_col)
    edge_rows = [r for r in range(h) 
                 if (r, min_col) in threes and (r, max_col) in threes]

    print(f"Edge cols: {edge_cols}")
    print(f"Edge rows: {edge_rows}")

    # Vertical edges: fill between 3s
    for col in edge_cols:
        rows = sorted([r for r in range(h) if (r, col) in threes])
        for i in range(len(rows) - 1):
            r1, r2 = rows[i], rows[i+1]
            for r in range(r1 + 1, r2):
                grid_output[r][col] = 2

    # Horizontal edges: fill between 3s
    for row in edge_rows:
        cols = sorted([c for c in range(w) if (row, c) in threes])
        for i in range(len(cols) - 1):
            c1, c2 = cols[i], cols[i+1]
            for c in range(c1 + 1, c2):
                grid_output[row][c] = 2

    return grid_output

result = apply_refined_rule(demo_input)

print("\n=== COMPARISON ===")
matches = 0
diffs = []
for r in range(len(demo_input)):
    for c in range(len(demo_input[0])):
        if result[r][c] != demo_output[r][c]:
            diffs.append((r, c, result[r][c], demo_output[r][c]))
        else:
