print(f"Matches: {matches} / {len(demo_output)}, Diffs: {len(diffs)}")
if diffs:
    print("Differences:")
    for r, c, got, expected in diffs:
        print(f"  ({r},{c}): got {got}, expected {expected}")

# Better rule: edge columns are min_col and max_col
def apply_better_rule(grid_input):
    grid_output = [row[:] for row in grid_input]

    h = len(grid_input)
    w = len(grid_input[0])

    # Find all 3s
    threes = set()
    for r in range(h):
        for c in range(w):
            if grid_input[r][c] == 3:
                threes.add((r, c))

    min_row = min(r for r, c in threes)
    max_row = max(r for r, c in threes)
    min_col = min(c for r, c in threes)
    max_col = max(c for r, c in threes)

    print(f"Bounding box: row[{min_row}-{max_row}], col[{min_col}-{max_col}]")

    # Vertical edges: only min_col and max_col
    for col in [min_col, max_col]:
        rows = sorted([r for r in range(h) if (r, col) in threes])
        print(f"Vertical edge at col {col}: 3s at rows {rows}")
        for i in range(len(rows) - 1):
            r1, r2 = rows[i], rows[i+1]
            for r in range(r1 + 1, r2):
                grid_output[r][col] = 2

    # Horizontal edges: only min_row and max_row
    for row in [min_row, max_row]:
        cols = sorted([c for c in range(w) if (row, c) in threes])
        print(f"Horizontal edge at row {row}: 3s at cols {cols}")
        for i in range(len(cols) - 1):
            c1, c2 = cols[i], cols[i+1]
            for c in range(c1 + 1, c2):
                grid_output[row][c] = 2

    return grid_output

result = apply_better_rule(demo_input)

print("\n=== COMPARISON ===")
matches = 0
diffs = []
for r in range(len(demo_input)):
    for c in range(len(demo_input[0])):
        if result[r][c] != demo_output[r][c]:
            diffs.append((r, c, result[r][c], demo_output[r][c]))
        else:
            matches += 1

print(f"Matches: {matches}, Diffs: {len(diffs)}")
if diffs:
